		if (!on) {
			Shape1.render(pose, vc, light, overlay);
		}

		float f1 = 2.5F;
		pose.translate(0.0, 1.0, 0.0);
		pose.mulPose(TechneModel.rotation(phi / f1, 1.0F, 0.0F, 0.0F));
		pose.translate(0.0, -1.0, 0.0);
		Shape9.render(pose, vc, light, overlay);
